    mg_ch('2. CRUD & Operators Mastery', 'Inserting Documents: insertOne, insertMany & Ordered vs Unordered Bulk Writes', 'mongodb insertOne insertMany, ordered false bulk insert, writeConcern mongodb',
        'Insert single documents with `insertOne()` and batches with `insertMany([...], { ordered: false })`—understanding how `ordered: false` handles duplicate-key errors across large batch imports.',
        ['**Atomicity Scope**: Every single-document write in MongoDB is **100% atomic** at the document level even without multi-document transactions!', '**`ordered: true` (Default) vs `ordered: false`**: With `ordered: true`, if document #3 out of 1,000 has a duplicate `_id`, documents #4–#1,000 abort immediately; with `{ ordered: false }`, MongoDB inserts all 999 valid documents in parallel and reports the 1 error at the end!'],
        [['`db.users.insertOne({...})`', 'Inserts 1 document and returns `insertedId`', 'Generates `_id: ObjectId(...)` client-side in the driver if omitted!'], ['`db.users.insertMany(docs, { ordered: false })`', 'Continues inserting remaining valid docs if one fails', 'Essential for idempotent high-throughput log/event ingestion!'], ['`writeConcern: { w: "majority", j: true }`', 'Waits for majority of replica set nodes + journal flush', 'Prevents rollback data loss on primary crash!']],
        "db.users.insertOne({ name: 'Kabir Mehta', email: 'kabir@nectra.dev', role: 'architect', active: true })",
