        [['question' => 'In db.users.insertMany(100Docs, { ordered: false }), what happens if document #5 violates a unique index?', 'answer' => 'MongoDB skips document #5, inserts the other 99 valid documents, and returns a BulkWriteError summary', 'options' => ['MongoDB skips document #5, inserts the other 99 valid documents, and returns a BulkWriteError summary', 'All 100 documents roll back automatically', 'Documents #6–#100 are skipped', 'The collection is locked']], ['question' => 'Where is a missing _id ObjectId generated by default during insertOne()?', 'answer' => 'Client-side inside the MongoDB Driver before transmitting BSON', 'options' => ['Client-side inside the MongoDB Driver before transmitting BSON', 'By an external UUID microservice', 'Only during compaction', 'Inside mongosh history']], ['question' => 'Which writeConcern guarantees durability across replica-set failover?', 'answer' => '{ w: "majority", j: true }', 'options' => ['{ w: "majority", j: true }', '{ w: 0 }', '{ w: 1, j: false }', '{ fsync: "never" }']]],
