        [['question' => 'Why is db.logs.drop() vastly faster than db.logs.deleteMany({}) when wiping an entire 50GB collection?', 'answer' => 'drop() unlinks the WiredTiger collection and index files immediately instead of deleting 50M index entries row by row', 'options' => ['drop() unlinks the WiredTiger collection and index files immediately instead of deleting 50M index entries row by row', 'deleteMany({}) requires a Replica Set', 'drop() keeps all indexes', 'deleteMany({}) only deletes 100 rows']], ['question' => 'Can replaceOne(filter, replacement) contain $set operators inside replacement?', 'answer' => 'No—replaceOne expects a plain replacement document without update operators', 'options' => ['No—replaceOne expects a plain replacement document without update operators', 'Yes, $set is mandatory', 'Only on sharded clusters', 'Only for _id']], ['question' => 'Which method sends mixed insert, update, and delete operations together in a single network round-trip?', 'answer' => 'db.collection.bulkWrite()', 'options' => ['db.collection.bulkWrite()', 'db.collection.multiExec()', 'db.collection.batchAll()', 'db.collection.pipeWrite()']]],
        'Test `db.orders.deleteOne({ orderNo: \'ORD-9002\' })` in the playground.'
