        [['question' => 'In what exact order MUST coordinates be stored inside a MongoDB GeoJSON Point?', 'answer' => '[longitude, latitude] (X, Y)', 'options' => ['[longitude, latitude] (X, Y)', '[latitude, longitude]', '[altitude, latitude, longitude]', '{ lat, lon }']], ['question' => 'How many text indexes can a single MongoDB collection have?', 'answer' => 'At most 1 (though it can span multiple string fields with custom weights)', 'options' => ['At most 1 (though it can span multiple string fields with custom weights)', 'Unlimited', 'Up to 64', 'Zero on WiredTiger']], ['question' => 'What unit of measurement does $maxDistance use when querying a 2dsphere GeoJSON index with $near?', 'answer' => 'Meters', 'options' => ['Meters', 'Miles', 'Radians only', 'Degrees']]],
        'Write a valid GeoJSON Point object for Bengaluru (`longitude: 77.5946, latitude: 12.9716`).'
